fn band_of(code: i32) -> i32 {
    match code {
        200..=299 => 0,
        300..400 => 1,
        400..=499 => 2,
        _ => 3,
    }
}

fn frame(t: i32) {
    host::display::clear(0x0c0c10);
    if host::display::state_get(0) == 0 {
        let h: i32 = host::http::get("https://example.com/missing-page", 32);
        host::display::state_set(1, h);
        if h < 0 {
            host::display::state_set(0, 3);
        } else {
            host::display::state_set(0, 1);
        }
    }
    let h2: i32 = host::display::state_get(1);
    if host::display::state_get(0) == 1 {
        let r: i32 = host::http::ready(h2);
        if r == 1 {
            host::display::state_set(0, 2);
        } else if r < 0 {
            host::display::state_set(0, 3);
        }
    }
    let phase: i32 = host::display::state_get(0);
    host::display::draw_string(90, 60, "STATUS CLASSIFIER", 0xffffff, 2);
    if phase == 1 {
        host::display::draw_string(190, 240, "WAITING", 0xaa7700, 2);
    } else if phase == 2 {
        let code: i32 = host::http::status(h2);
        let band: i32 = band_of(code);
        host::display::draw_number(180, 150, code, 0xffffff, 6);
        if band == 0 {
            host::display::fill_rect(150, 260, 212, 60, 0x1a5c2a);
            host::display::draw_string(220, 280, "OK", 0x66ff99, 3);
        } else if band == 1 {
            host::display::fill_rect(150, 260, 212, 60, 0x6b5416);
            host::display::draw_string(184, 280, "REDIRECT", 0xffcc44, 2);
        } else if band == 2 {
            host::display::fill_rect(150, 260, 212, 60, 0x5c1a1a);
            host::display::draw_string(160, 280, "CLIENT ERROR", 0xff8877, 2);
        } else {
            host::display::fill_rect(150, 260, 212, 60, 0x3a1a5c);
            host::display::draw_string(160, 280, "SERVER ERROR", 0xcc99ff, 2);
        }
    } else {
        host::display::draw_string(130, 240, "FETCH DENIED", 0xbb3333, 2);
        host::display::draw_string(96, 280, "NO UPSTREAM STATUS TO CLASSIFY", 0x777777, 1);
    }
    host::display::present();
}
